        /// gpui `overflow_hidden`.
        pub fn overflowHidden(self: Self) Self {
            return blk: {
                var s = self;
                const r = s.style();
                r.overflow.x = style.Overflow.hidden;
                r.overflow.y = style.Overflow.hidden;
                break :blk s;
            };
        }
